@contextmanager
def as_silent(self) -> Iterator[None]:
    original_stdout = self.stdout
    original_stderr = self.stderr

    try:
        self.stdout = self.devnull
        self.stderr = self.devnull
        yield
    finally:
        self.stdout = original_stdout
        self.stderr = original_stderr

